<?php
require "../config/database.php";require "../config/auth.php";require_role("admin");$title="Admin Dashboard";$counts=[];
foreach(["users","students","companies","jobs","applications"] as $t)$counts[$t]=$db->query("SELECT COUNT(*) n FROM $t")->fetch()["n"];
include "../includes/header.php";?><h2>Admin Dashboard</h2><div class="row"><?php foreach($counts as $k=>$v):?><div class="col-md-2 mb-3"><div class="card shadow-sm"><div class="card-body"><small><?=e(ucfirst($k))?></small><h2><?=$v?></h2></div></div></div><?php endforeach;?></div>
<div class="card"><div class="card-body"><h4>Recent Applications</h4><?php $r=$db->query("SELECT u.name,j.title,c.company_name,a.status FROM applications a JOIN students s ON s.id=a.student_id JOIN users u ON u.id=s.user_id JOIN jobs j ON j.id=a.job_id JOIN companies c ON c.id=j.company_id ORDER BY a.applied_at DESC LIMIT 20")->fetchAll();?><table class="table"><tr><th>Student</th><th>Job</th><th>Company</th><th>Status</th></tr><?php foreach($r as $x):?><tr><td><?=e($x["name"])?></td><td><?=e($x["title"])?></td><td><?=e($x["company_name"])?></td><td><?=e($x["status"])?></td></tr><?php endforeach;?></table></div></div><?php include "../includes/footer.php";?>